mapper.select:
select count(*) from _post_like 
where post_id = #{post_id} 
and member_id = #{member_id}

mapper.delete:
delete from _post_like 
where post_id = #{post_id} 
and member_id = #{member_id}

mapper.select:
select count(*) from _comment_like 
where comment_id = #{comment_id} 
and member_id = #{member_id}

mapper.delete:
delete from _comment_like 
where comment_id = #{comment_id} 
and member_id = #{member_id}

mapper.update:
update _post set 
post_title = #{post_title}, post_content = #{post_content}, post_type = #{post_type}, post_resion = #{post_resion}, 
pet_code = #{pet_code}, pet_etc_breed = #{pet_etc_breed}, post_pet_place = #{post_pet_place}, post_pet_date = #{post_pet_date} 
where post_id = #{post_id}

mapper.select:
select p.*, ct.*, m.*, i.image_sequence, i.image_src, count(pl.member_id) as post_like_count from _post p 
join _image i on p.post_id = i.image_id 
join _category_data ct on p.pet_code = ct.category_code 
join _member m on p.member_id = m.member_id 
left join _post_like pl on p.post_id = pl.post_id 
where p.post_type = #{post_type} 
and p.post_resion = #{post_resion} 
and ct.category_parent = #{category_parent} 
group by p.post_id, i.image_sequence, i.image_src 
order by p.post_date desc
